// LOCAL TYPECHECK STUB
//
// This file is generated by `prisma generate` inside the Docker builder
// stage (which runs Debian and can fetch Prisma's engine binaries). On the
// host machine (NixOS) Prisma cannot fetch its engines so the directory is
// populated with this minimal stub so TypeScript can resolve the imports
// in `src/lib/db.ts` and consumers. The Dockerfile's `prisma generate`
// step replaces this directory before the standalone build artefact is
// produced, so this stub never ships in the deployed image.
//
// We use an index signature so callers (`prisma.user`, `prisma.space`,
// `prisma.$queryRaw`, etc.) all typecheck without us hand-maintaining
// model definitions that the generator would otherwise own.

declare class PrismaClient {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
  constructor(options?: unknown);
}

export { PrismaClient };
export default PrismaClient;
